library(biomartr)
library(tidyverse)
library(readxl)

Accessions_Metadata <- read_excel("Data/20230928_Accessions_Metadata.xlsx")


for (i in 1:nrow(Accessions_Metadata)){
  if (Accessions_Metadata$accession_sample[i] == "NA"){
    if (str_detect(Accessions_Metadata$accession_assembly[i], "GCF")){
      biosample <- is.genome.available(db = "refseq", organism = Accessions_Metadata$accession_assembly[i], details = TRUE) 
    }else if(str_detect(Accessions_Metadata$accession_assembly[i], "GCA")){
      biosample <- is.genome.available(db = "genbank", organism = Accessions_Metadata$accession_assembly[i], details = TRUE) 
    }
    if (!is.logical(biosample)){
      Accessions_Metadata$accession_sample[i] = biosample %>% pull(biosample)
    }
    }
}

write_tsv(Accessions_Metadata,"Data/20230929_Accessions_Metadata.tsv")

